import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
class FeedScreen extends StatefulWidget{const FeedScreen({super.key});@override State<FeedScreen> createState()=>_FeedScreenState();}
class _FeedScreenState extends State<FeedScreen>{
 Future<List<Map<String,dynamic>>> load() async {final r=await Supabase.instance.client.from('posts').select('*,profiles(username,avatar_url)').order('created_at',descending:true).limit(50);return List<Map<String,dynamic>>.from(r);}
 Future<void> like(String id) async {final u=Supabase.instance.client.auth.currentUser;if(u==null)return;try{await Supabase.instance.client.from('likes').insert({'post_id':id,'user_id':u.id});}catch(_){}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('FOCUS',style:TextStyle(fontWeight:FontWeight.bold))),body:FutureBuilder<List<Map<String,dynamic>>>(future:load(),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('Feed unavailable: ${s.error}'));final posts=s.data??[];if(posts.isEmpty)return const Center(child:Text('No posts yet. Create the first post!'));return RefreshIndicator(onRefresh:()=>setState(()=>{}),child:ListView.builder(itemCount:posts.length,itemBuilder:(context,i){final p=posts[i];final profile=p['profiles']??{};return Card(margin:const EdgeInsets.all(10),clipBehavior:Clip.antiAlias,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(profile['username']??'FOCUS user'),subtitle:Text((p['created_at']??'').toString().split('T').first)),if(p['media_url']!=null)Image.network(p['media_url'],width:double.infinity,height:300,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const SizedBox(height:180,child:Center(child:Icon(Icons.broken_image)))),Row(children:[IconButton(onPressed:()=>like(p['id'].toString()),icon:const Icon(Icons.favorite_border)),IconButton(onPressed:(){},icon:const Icon(Icons.comment_outlined)),IconButton(onPressed:(){},icon:const Icon(Icons.share_outlined))]),Padding(padding:const EdgeInsets.all(12),child:Text(p['caption']??''))]));}));}));
}
